/* @lc app=leetcode id=3677 lang=kotlin */ class Solution { fun countBinaryPalindromes(n: Long): Int = if (n == 0L) 1 else java.lang.Long.toBinaryString(n).let { s -> s.length.let { L -> ((L + 1) / 2).let { h -> s.take(h).let { half -> 1 + (1 until L).sumOf { 1L shl ((it + 1) / 2 - 1) } + (half.toLong(2) - (1L shl (h - 1))) + (if ((half + half.reversed().drop(L % 2)).toLong(2) <= n) 1 else 0) } } } }.toInt() }